static NSUInteger checks;
static void Check(BOOL ok,NSString *message){checks++;if(!ok){fprintf(stderr,"FAIL: %s\n",message.UTF8String);exit(1);}}
static void Drain(void){[NSRunLoop.mainRunLoop runUntilDate:[NSDate dateWithTimeIntervalSinceNow:.15]];}
static NSUInteger SplitCount(NSView *view){NSUInteger count=[view isKindOfClass:NSSplitView.class] ? 1:0;for(NSView *child in view.subviews)count+=SplitCount(child);return count;}
@interface EvaluationAPI:SSGitHub
@property NSString *body;
@end
@implementation EvaluationAPI
- (id)readRepository:(NSString *)repository resource:(NSString *)resource error:(NSError **)error {return @{@"body":self.body};}
@end
@interface ImageAPI:SSGitHub
